import numpy as np, warnings
warnings.filterwarnings('ignore')
from scipy.optimize import least_squares
eps=df['eps'].values;T=df['T'].values;s=df['sigma'].values
V=np.var(s)
def cols(nl, deg, mode):
    c,k,p=nl
    base=[eps**2, np.exp(-c*T)*eps**1.5, np.tanh(k*eps)]
    if mode=='poly':
        extra=[eps**p*T**j for j in range(deg+1)]
    else:
        extra=[eps**(p+j*0.5)*np.ones_like(T) for j in range(deg+1)]
    return np.column_stack(base+extra)
def resid(nl,deg,mode):
    X=cols(nl,deg,mode)
    X=np.nan_to_num(X,nan=0,posinf=0,neginf=0)
    coef,_,_,_=np.linalg.lstsq(X,s,rcond=None)
    return X@coef-s
for deg in [0,1,2,3]:
    best=None
    for c0 in [0.1,0.2,0.4]:
      for k0 in [-0.5,-0.3,0.3,1.0]:
        for p0 in [0.5,1.0,2.0,3.0]:
          try:
            r=least_squares(resid,[c0,k0,p0],args=(deg,'poly'),max_nfev=200)
          except Exception: continue
          if best is None or r.cost<best.cost: best=r
    print('deg',deg,'NMSE',2*best.cost/len(s)/V, np.round(best.x,4))

